mapper.select:
SELECT ranked.* FROM ( SELECT scored.*, CASE WHEN scored.max_view_log = 0 THEN 0 ELSE scored.view_log / scored.max_view_log END AS view_score, CASE WHEN scored.max_abs_like_log = 0 THEN 0.5 ELSE 0.5 + scored.signed_like_log / (2 * scored.max_abs_like_log) END AS like_score, CASE WHEN scored.max_comment_log = 0 THEN 0 ELSE scored.comment_log / scored.max_comment_log END AS comment_score, CASE WHEN scored.age_hours < 0 THEN 0 ELSE POW(0.5, scored.age_hours / 72.0) END AS time_score, ( 0.10 * CASE WHEN scored.max_view_log = 0 THEN 0 ELSE scored.view_log / scored.max_view_log END + 0.25 * CASE WHEN scored.max_abs_like_log = 0 THEN 0.5 ELSE 0.5 + scored.signed_like_log / (2 * scored.max_abs_like_log) END + 0.25 * CASE WHEN scored.max_comment_log = 0 THEN 0 ELSE scored.comment_log / scored.max_comment_log END + 0.40 * CASE WHEN scored.age_hours < 0 THEN 0 ELSE POW(0.5, scored.age_hours / 72.0) END ) AS hot_score FROM ( SELECT base.*, MAX(base.view_log) OVER () AS max_view_log, MAX(base.comment_log) OVER () AS max_comment_log, MAX(ABS(base.signed_like_log)) OVER () AS max_abs_like_log FROM ( SELECT , IFNULL(view_stats.viewers24, 0) AS viewers24, IFNULL(comment_stats.top_comments, 0) AS top_comments, IFNULL(p.like_count, 0) AS net_like, GREATEST(TIMESTAMPDIFF(HOUR, p.create_time, NOW()), 0) AS age_hours, LOG(1 + IFNULL(view_stats.viewers24, 0)) AS view_log, LOG(1 + IFNULL(comment_stats.top_comments, 0)) AS comment_log, CASE WHEN IFNULL(p.like_count, 0) = 0 THEN 0 ELSE SIGN(IFNULL(p.like_count, 0)) * LOG(1 + ABS(IFNULL(p.like_count, 0))) END AS signed_like_log
LEFT JOIN ( SELECT br.target_id, COUNT(DISTINCT br.user_id) AS viewers24 FROM browse_records br WHERE br.target = 'POST' AND br.create_time >= DATE_SUB(NOW(), INTERVAL 24 HOUR) GROUP BY br.target_id ) view_stats ON view_stats.target_id = p.id LEFT JOIN ( SELECT c.target_id, COUNT(1) AS top_comments FROM comments c WHERE c.target = 'POST' AND c.parent_id = 0 AND c.is_deleted = 0 GROUP BY c.target_id ) comment_stats ON comment_stats.target_id = p.id
) base ) scored ) ranked ORDER BY ranked.hot_score DESC, ranked.create_time DESC, ranked.id DESC

SELECT p.id, p.title, p.content, p.like_count AS likeCount, p.comment_count AS commentCount, p.create_time AS createTime, b.name AS boardName, b.cover AS boardCover FROM posts p LEFT JOIN boards b ON p.board_id = b.id
AND p.id IN
#{id}
AND 1 = 0
AND p.is_deleted = 0
ORDER BY FIELD(p.id,
#{id}
)
